212	func (s *service) modelInfoFromSnapshotModel(ctx context.Context, providerName string, entry ServiceProviderEntry, defaultProviderName string, cat *modelcatalog.Catalog, model modelsnapshot.KnownModel, rankPosition int) ModelInfo {
213		info := ModelInfo{
214			ID:              model.ID,
215			Provider:        providerName,
216			ProviderType:    model.ProviderType,
217			Harness:         model.Harness,
218			EndpointName:    model.EndpointName,
219			EndpointBaseURL: model.EndpointBaseURL,
220			ServerInstance:  model.ServerInstance,
221			ContextLength:   model.ContextWindow,
222			Utilization:     s.routeUtilizationEvidence(providerName, model.ServerInstance, model.EndpointName, model.ID),
223			Capabilities:    providerCapabilities(entry),
224			Cost: CostInfo{
225				InputPerMTok:  model.CostInputPerM,
226				OutputPerMTok: model.CostOutputPerM,
227			},
228			Power:                         model.Power,
229			AutoRoutable:                  model.AutoRoutable,
230			ExactPinOnly:                  model.ExactPinOnly,
231			Billing:                       model.Billing,
232			ActualCashSpend:               model.ActualCashSpend,
233			EffectiveCost:                 model.EffectiveCost,
234			EffectiveCostSource:           model.EffectiveCostSource,
235			SupportsTools:                 model.SupportsTools,
236			DeploymentClass:               model.DeploymentClass,
237			HealthFreshnessAt:             model.HealthFreshnessAt,
238			HealthFreshnessSource:         model.HealthFreshnessSource,
239			QuotaFreshnessAt:              model.QuotaFreshnessAt,
240			QuotaFreshnessSource:          model.QuotaFreshnessSource,
241			ModelDiscoveryFreshnessAt:     model.DiscoveredAt,
242			ModelDiscoveryFreshnessSource: string(model.DiscoveredVia),
243			Available:                     true,
244			RankPosition:                  rankPosition,
245		}
246		if info.Harness == "" {
247			info.Harness = "fiz"
248		}
249		info.ContextLength, info.ContextSource = resolveContextEvidence(ctx, entry, model.ID, cat)
250		if cat != nil {
251			_, info.PerfSignal = catalogCostAndPerf(cat, model.ID)
252		}
253		info.IsDefault = providerName == defaultProviderName && entry.Model != "" && model.ID == entry.Model
254		return info
255	}
