142	func routeDecisionFromInternal(dec *routing.Decision, powerPolicy RoutePowerPolicy) *RouteDecision {
143		if dec == nil {
144			return nil
145		}
146		return &RouteDecision{
147			Harness:        dec.Harness,
148			Provider:       dec.Provider,
149			Endpoint:       dec.Endpoint,
150			ServerInstance: dec.ServerInstance,
151			Model:          dec.Model,
152			Reason:         dec.Reason,
153			Candidates:     routeCandidatesFromInternal(dec.Candidates, powerPolicy),
154		}
155	}
156	
157	func routeCandidatesFromInternal(candidates []routing.Candidate, powerPolicy RoutePowerPolicy) []RouteCandidate {
158		if len(candidates) == 0 {
159			return nil
160		}
161		out := make([]RouteCandidate, len(candidates))
162		for i, candidate := range candidates {
163			out[i] = routeCandidateFromInternal(candidate, powerPolicy)
164		}
165		return out
166	}
167	
168	func routeCandidateFromInternal(candidate routing.Candidate, powerPolicy RoutePowerPolicy) RouteCandidate {
169		components := RouteCandidateComponents{
170			Power:            candidate.Power,
171			Cost:             candidate.CostUSDPer1kTokens,
172			CostClass:        candidate.CostClass,
173			LatencyMS:        candidate.LatencyMS,
174			SpeedTPS:         candidate.SpeedTPS,
175			Utilization:      candidate.Utilization,
176			SuccessRate:      candidate.SuccessRate,
177			QuotaOK:          candidate.QuotaOK,
178			QuotaPercentUsed: candidate.QuotaPercentUsed,
179			QuotaTrend:       candidate.QuotaTrend,
180			Capability:       capabilityScoreForCostClass(candidate.CostClass),
181			ContextHeadroom:  candidate.ContextHeadroom,
182			StickyAffinity:   candidate.StickyAffinity,
183		}
184		powerHintFit := scorePowerHintFit(candidate, powerPolicy)
185		scorePower := candidate.ScoreComponents["power"]
186		scoreCost := candidate.ScoreComponents["cost"]
187		scorePerformance := candidate.ScoreComponents["performance"]
188		scoreLocality := candidate.ScoreComponents["deployment_locality"]
189		scoreQuota := candidate.ScoreComponents["quota_health"]
190		scoreUtilization := candidate.ScoreComponents["utilization"]
191		components.PowerHintFit = powerHintFit
192		components.PowerWeightedCapability = scorePower - powerHintFit + positiveScorePart(scoreCost)
193		components.LatencyWeight = positiveScorePart(scorePerformance)
194		components.StaleSignalPenalty = positiveScorePart(-scorePerformance)
195		components.PlacementBonus = scoreLocality + candidate.StickyAffinity
196		components.QuotaBonus = positiveScorePart(scoreQuota)
197		components.MarginalCostPenalty = positiveScorePart(-scoreCost)
198		components.AvailabilityPenalty = positiveScorePart(-scoreQuota) + positiveScorePart(-scoreUtilization)
199		return RouteCandidate{
200			Harness:             candidate.Harness,
201			Provider:            candidate.Provider,
202			Billing:             candidate.Billing,
203			ActualCashSpend:     candidate.ActualCashSpend,
204			Endpoint:            candidate.Endpoint,
205			ServerInstance:      candidate.ServerInstance,
206			Model:               candidate.Model,
207			Score:               candidate.Score,
208			CostUSDPer1kTokens:  candidate.CostUSDPer1kTokens,
209			CostSource:          candidate.CostSource,
210			EffectiveCost:       candidate.CostUSDPer1kTokens,
211			EffectiveCostSource: candidate.CostSource,
212			Eligible:            candidate.Eligible,
213			Reason:              candidate.Reason,
214			FilterReason:        publicFilterReason(candidate),
215			ContextLength:       candidate.ContextLength,
216			ContextSource:       candidate.ContextSource,
217			Components:          components,
218			ScoreComponents:     copyScoreComponents(candidate.ScoreComponents),
219		}
220	}
221	
222	func copyScoreComponents(in map[string]float64) map[string]float64 {
223		if len(in) == 0 {
224			return nil
225		}
226		out := make(map[string]float64, len(in))
227		for k, v := range in {
228			out[k] = v
229		}
230		return out
231	}
232	
233	func scorePowerHintFit(candidate routing.Candidate, policy RoutePowerPolicy) float64 {
234		power := candidate.Power
235		if power <= 0 {
236			return 0
237		}
238		if policy.MaxPower > 0 && candidate.FilterReason == routing.FilterReasonAboveMaxPower && candidate.ScoreComponents != nil {
239			return candidate.ScoreComponents["power"]
240		}
241		if policy.MinPower > 0 && power < policy.MinPower {
242			// Mirror the engine scorer: materially underpowered routes should not
243			// win just because they are cheap.
244			return -float64(policy.MinPower-power) * 12
245		}
246		if policy.MaxPower > 0 && power > policy.MaxPower {
247			return -float64(power - policy.MaxPower)
248		}
249		return 0
250	}
251	
252	func positiveScorePart(v float64) float64 {
253		if v > 0 {
254			return v
255		}
256		return 0
257	}
