588	func publicRoutingError(err error, candidates []RouteCandidate, requestedPolicy ...string) error {
589		displayPolicy := func(policy string) string {
590			if len(requestedPolicy) > 0 && requestedPolicy[0] != "" {
591				return requestedPolicy[0]
592			}
593			return policy
594		}
595		var modelErr *routing.ErrHarnessModelIncompatible
596		if errors.As(err, &modelErr) {
597			return withRouteCandidates(&ErrHarnessModelIncompatible{
598				Harness:         modelErr.Harness,
599				Model:           modelErr.Model,
600				SupportedModels: append([]string(nil), modelErr.SupportedModels...),
601			}, candidates)
602		}
603		var policyErr *routing.ErrPolicyRequirementUnsatisfied
604		if errors.As(err, &policyErr) {
605			return withRouteCandidates(&ErrPolicyRequirementUnsatisfied{
606				Policy:       displayPolicy(policyErr.Policy),
607				Requirement:  policyErr.Requirement,
608				AttemptedPin: policyErr.AttemptedPin,
609				Rejected:     policyErr.Rejected,
610			}, candidates)
611		}
612		var unknownPolicyErr *routing.ErrUnknownPolicy
613		if errors.As(err, &unknownPolicyErr) {
614			return withRouteCandidates(&ErrUnknownPolicy{
615				Policy: displayPolicy(unknownPolicyErr.Policy),
616			}, candidates)
617		}
618		var pinErr *routing.ErrUnsatisfiablePin
619		if errors.As(err, &pinErr) {
620			return withRouteCandidates(&ErrUnsatisfiablePin{
621				Pin:    pinErr.Pin,
622				Reason: pinErr.Reason,
623			}, candidates)
624		}
625		var noLiveErr *routing.ErrNoLiveProvider
626		if errors.As(err, &noLiveErr) {
627			return withRouteCandidates(&ErrNoLiveProvider{
628				PromptTokens:   noLiveErr.PromptTokens,
629				RequiresTools:  noLiveErr.RequiresTools,
630				StartingPolicy: displayPolicy(noLiveErr.StartingPolicy),
631			}, candidates)
632		}
633		var quotaErr *routing.ErrAllProvidersQuotaExhausted
634		if errors.As(err, &quotaErr) {
635			return withRouteCandidates(&NoViableProviderForNow{
636				RetryAfter:         quotaErr.RetryAfter,
637				ExhaustedProviders: append([]string(nil), quotaErr.ExhaustedProviders...),
638			}, candidates)
639		}
640		return withRouteCandidates(err, candidates)
641	}
