106	// subscriptionHarnessTierModels builds the tier ModelInfos for a single
107	// subprocess subscription harness, drawing model IDs from the harness's
108	// documented CLI surface and cross-referencing the model catalog for power,
109	// cost, and context metadata. It returns nil when the harness exposes no model
110	// IDs. Shared by the harness-pinned ListModels path and the unfiltered path.
111	func (s *service) subscriptionHarnessTierModels(name string, cfg harnesses.HarnessConfig, cat *modelcatalog.Catalog) []ModelInfo {
112		modelIDs := subprocessHarnessModelIDs(name, cfg)
113		if len(modelIDs) == 0 {
114			return nil
115		}
116		out := make([]ModelInfo, 0, len(modelIDs))
117		for i, id := range modelIDs {
118			info := ModelInfo{
119				ID:             id,
120				Provider:       name,
121				Harness:        name,
122				EndpointName:   name,
123				ServerInstance: name,
124				Capabilities:   []string{"streaming", "tool_use"},
125				Available:      true,
126				IsDefault:      cfg.DefaultModel != "" && id == cfg.DefaultModel,
127				Billing:        harnessPaymentKind(name, cfg),
128				RankPosition:   i,
129			}
130			if cat != nil {
131				info.ContextLength, info.ContextSource = resolveContextEvidence(context.Background(), ServiceProviderEntry{}, id, cat)
132				info.Cost, info.PerfSignal = catalogCostAndPerf(cat, id)
133				info.Power, info.AutoRoutable, info.ExactPinOnly = catalogPowerEligibility(cat, id)
134			}
135			info.Utilization = s.routeUtilizationEvidence(name, info.ServerInstance, info.EndpointName, id)
136			out = append(out, info)
137		}
138		return out
139	}
